#!/usr/bin/env python3
"""Install the reviewed final manuscript exactly and synchronize the canonical alias."""
from pathlib import Path
import base64, hashlib, zlib
ROOT=Path(__file__).resolve().parents[1]
PAPER=ROOT/'docs/paper/paper.md'
ALIAS=ROOT/'docs/paper/paper-draft.md'
EXPECTED_SHA256='8f7aaf1a7c3c5979a7fec724731f1ed0217a22fd2b1a8c12b79ec11a8a42ae7f'
PAYLOAD='[... ELLIPSIZATION ...]'
def main():
    data=zlib.decompress(base64.b64decode(PAYLOAD))
    digest=hashlib.sha256(data).hexdigest()
    if digest!=EXPECTED_SHA256:
        raise SystemExit(f'final manuscript payload hash mismatch: {digest}')
    text=data.decode('utf-8')
    if '63%-71% under Jeffreys alpha=0.5 and 47%-53% under alpha=1' not in text:
        raise SystemExit('final manuscript marker missing')
    PAPER.write_bytes(data); ALIAS.write_bytes(data)
    print(f'sync_final_paper: installed canonical manuscript sha256={digest}')
if __name__=='__main__': main()
